import request from '../utils/request'

export function getPlanInfo(params) {
  return request({
    url: '/plan/info',
    method: 'get',
    params
  })
}

export function isPro(params) {
  return request({
    url: '/subscription/isPro',
    method: 'get',
    params
  })
}


export function renew(data) {
  return request.post('/subscription/resume', data, {
    headers: { 'Content-Type': 'application/json' },
  })
}


export function unsubscribe(data) {
  return request.post('/subscription/cancel', data, {
    headers: { 'Content-Type': 'application/json' },
  })
}