<script>
import { usePlanStore } from "../../../store/planStore";
import { useAuthStore } from "../../../store/authStore.js";
import { APP_ID, APP_VERSION } from "../../../utils/config.js";
import { useI18n } from "../../../utils/i18n";

export default {
  name: "CustomTable",
  data() {
    return {
      t: null,
      agree: true,
      planType: "one_time",
      selectedIndex: 0,
      oneTimeSelectedIndex: 0,
      planStore: usePlanStore(),
      store: useAuthStore(),
    };
  },
  created() {
    const { t } = useI18n();
    this.t = t; // Assign t from useI18n to the data property
  },
  watch: {
    "data.subs": {
      immediate: true,
      handler(newSubs) {
        if (newSubs && newSubs.length > 0) {
          if (this.oneTimePlans.length > 0) {
            this.planType = "one_time";
            this.oneTimeSelectedIndex = 0;
            return;
          }
          const badgeIndex = this.subscriptionPlans.findIndex(
            (sub) => sub.has_badge
          );
          if (badgeIndex !== -1) {
            this.selectedIndex = badgeIndex;
          }
          if (this.subscriptionPlans.length > 0) {
            this.planType = "subscription";
            this.selectedIndex = Math.max(this.selectedIndex, 0);
          }
        }
      },
    },
  },
  computed: {
    data() {
      const planInfo = this.planStore.planInfo;
      if (!planInfo) return { text: "", subs: [] }; // Default values

      return {
        text: planInfo.promo,
        subs: planInfo.plans,
      };
    },
    promoShow() {
      if (this.currentPlan) {
        return this.currentPlan.pormo_show;
      }
    },
    currentPrice() {
      if (this.currentPlan) {
        return this.currentPlan.price;
      }
    },
    currentPormo() {
      if (this.currentPlan) {
        return this.currentPlan.promo;
      }
    },
    currentName() {
      if (this.currentPlan) {
        return this.currentPlan.name;
      }
    },
    subscriptionPlans() {
      return this.data.subs.filter((plan) => {
        const mode = (plan.billing_mode || "").toLowerCase();
        return mode !== "one_time";
      });
    },
    oneTimePlans() {
      return this.data.subs.filter((plan) => {
        const mode = (plan.billing_mode || "").toLowerCase();
        return mode === "one_time";
      });
    },
    currentPlan() {
      if (this.planType === "one_time") {
        return this.oneTimePlans[this.oneTimeSelectedIndex] || null;
      }
      return this.subscriptionPlans[this.selectedIndex] || null;
    },
    hasOneTime() {
      return this.oneTimePlans.length > 0;
    },
    hasSubscription() {
      return this.subscriptionPlans.length > 0;
    },
    isPro() {
      return this.planStore.pro;
    },
    uid() {
      return this.store.user ? this.store.user.uid : "";
    },
    isCancelled() {
      return this.planStore.planInfo.status == "cancelled";
    },
    items() {
      return [
        {
          content: [this.$t("individual_download.message"), " (*.jpg)"],
          freeIcon: "green",
          proHas: true,
        },
        {
          content: [
            this.$t("one_click_download_images.message"),
            " (*.zip, *.xlsx)",
          ],
          freeIcon: "gray",
          proHas: true,
        },
        {
          content: [this.$t("download_videos.message"), " (*.mp4)"],
          freeIcon: "gray",
          proHas: true,
        },
      ];
    },
  },
  methods: {
    subscribe() {
      if (!this.agree) {
        alert($t("agreeTerms.message"));
        return;
      }
      if (!this.currentPlan) {
        return;
      }
      const baseUrl = import.meta.env.VITE_PAYOUT_URL;
      const params = {
        plan: this.currentName,
        app: APP_ID,
        uid: this.uid,
        ver: APP_VERSION,
      };
      const query = new URLSearchParams(params).toString();
      const urlWithParams = `${baseUrl}?${query}`;

      chrome.tabs.create({ url: urlWithParams });
    },
    unsubscribe() {
      const data = {
        id: this.planStore.planInfo.proId,
      };
      this.planStore.unsubscribe(data);
    },
    openSubscriptionPage() {
      chrome.tabs.create({ url: "https://app.lemonsqueezy.com/my-orders" });
    },
    async renew() {
      const data = {
        id: this.planStore.planInfo.proId,
      };
      const rt = await this.planStore.renew(data);
      if (!rt) {
        chrome.tabs.create({ url: "https://webstar.lemonsqueezy.com/billing" });
      }
    },
    getLocalizedMessage(key) {
      return chrome.i18n.getMessage(key);
    },
  },
};
</script>

