<script>
import JSZip from "jszip";
import { saveAs } from "file-saver";
import * as XLSX from "xlsx";
import { usePlanStore } from "../../../store/planStore";
import { useAuthStore } from "../../../store/authStore.js";
import {
  downloadVideo,
  downloadSingleImage,
  downloadImagesZip,
  downloadAllImages,
} from "../../../utils/downloadUtil";
import { SITE } from "../../../utils/config.js";
import { useI18n } from "../../../utils/i18n";
import {
  canDownloadSingleImage,
  incrementSingleImageDownloadCount,
  getRemainingSingleImageDownloads,
  FREE_SINGLE_IMAGE_DOWNLOADS_PER_DAY,
} from "../../../utils/limitUtil";

export default {
  data() {
    return {
      t: null,
      planStore: usePlanStore(),
      authStore: useAuthStore(),
      currentTab: "image",
      videoProgresses: new Array(this.videosCount).fill(-1),
      imageProgresses: new Array(3).fill(-1),
      allImagesProgress: -1,
      remainingSingleImages: FREE_SINGLE_IMAGE_DOWNLOADS_PER_DAY,
    };
  },
  created() {
    const { t } = useI18n();
    this.t = t; // Assign t from useI18n to the data property
    this.updateRemainingDownloads();
  },
  computed: {
    hasLoadedPlan() {
      return !this.planStore.isLoading && this.planStore.planInfo !== null;
    },
    isFreeUser() {
      return this.hasLoadedPlan && !this.planStore.pro;
    },
    isVideoDownloading() {
      return (index) =>
        this.videoProgresses[index] >= 0 && this.videoProgresses[index] < 100;
    },
    isImageDownloading() {
      return (index) =>
        this.imageProgresses[index] >= 0 && this.imageProgresses[index] < 100;
    },
    totalImagesCount() {
      return (
        this.productData.mainImages.length +
        this.productData.categoryImages.length +
        this.productData.descriptionImages.length
      );
    },
    productData() {
      var product = this.planStore.product;
      if (!product)
        return {
          isProduct: false,
          title: "",
          mainImages: [],
          categoryImages: [],
          descriptionImages: [],
        }; // Default values
      return product;
    },
    imagesCount() {
      var product = this.planStore.product;
      if (!product) return 0; // Default values
      return (
        product.mainImages.length +
        product.categoryImages.length +
        product.descriptionImages.length
      );
    },
  },
  methods: {
    updateRemainingDownloads() {
      this.remainingSingleImages = getRemainingSingleImageDownloads();
    },
    goToVip() {
      this.authStore.activeTabIndex = 3;
    },
    requireProFeature() {
      if (this.planStore.pro) {
        return true;
      }
      if (!this.hasLoadedPlan) {
        return false;
      }
      this.goToVip();
      return false;
    },
    async convertWebPToJPEG(blob) {
      return new Promise((resolve, reject) => {
        const canvas = document.createElement("canvas");
        const ctx = canvas.getContext("2d");
        const img = new Image();

        img.onload = () => {
          canvas.width = img.width;
          canvas.height = img.height;
          ctx.drawImage(img, 0, 0);
          canvas.toBlob(resolve, "image/jpeg");
        };

        img.onerror = reject;
        img.src = URL.createObjectURL(blob);
      });
    },

    async downloadImage(type, index, image) {
      if (!this.planStore.pro && !canDownloadSingleImage()) {
        this.goToVip();
        return;
      }

      let fileName = "image";
      if (type === "variant") {
        fileName = `${SITE}_${type}_${index}`;
      } else {
        fileName = `${SITE}_${type}_${index}`;
      }
      await downloadSingleImage(fileName, image);

      if (
        !this.planStore.pro &&
        Number.isFinite(FREE_SINGLE_IMAGE_DOWNLOADS_PER_DAY)
      ) {
        incrementSingleImageDownloadCount();
        this.updateRemainingDownloads();
      }
    },
    async downloadAllImages() {
      if (!this.requireProFeature()) {
        return;
      }

      this.allImagesProgress = 0;

      try {
        await downloadAllImages(
          this.productData.title,
          this.productData.categoryImages,
          this.productData.mainImages,
          this.productData.descriptionImages,
          (progress) => {
            if (progress === 100) {
              // Set to 100% briefly and then immediately set to -1 to show completion
              this.allImagesProgress = 100;
              this.allImagesProgress = -1;
            } else {
              this.allImagesProgress = progress;
            }
          }
        );
      } catch (error) {
        console.error("Error downloading all images:", error);
        this.allImagesProgress = -1;
      }
    },

    async downloadVideo(videoUrl, index) {
      if (!this.requireProFeature()) {
        return;
      }

      this.videoProgresses[index] = 0;
      try {
        await downloadVideo(
          this.productData.title,
          index,
          videoUrl,
          (progress) => {
            this.videoProgresses[index] = progress;
          }
        );
      } catch (error) {
        console.error("Download video failed", error);
      }
    },

    downloadAllExcel() {
      if (!this.requireProFeature()) {
        return;
      }

      let hasDownloaded = false;

      const workbook = XLSX.utils.book_new();

      if (this.productData.categoryImages.length > 0) {
        const variantData = this.productData.categoryImages.map((img) => ({
          variant: img.name,
          image: img.image,
          title: this.productData.title,
        }));
        const variantSheet = XLSX.utils.json_to_sheet(variantData);
        XLSX.utils.book_append_sheet(workbook, variantSheet, "variant");
        hasDownloaded = true;
      }

      if (this.productData.mainImages.length > 0) {
        const mainData = this.productData.mainImages.map((img) => ({
          image: img,
        }));
        const mainSheet = XLSX.utils.json_to_sheet(mainData);
        XLSX.utils.book_append_sheet(workbook, mainSheet, "main");
        hasDownloaded = true;
      }

      if (this.productData.descriptionImages.length > 0) {
        const descData = this.productData.descriptionImages.map((img) => ({
          image: img,
        }));
        const descSheet = XLSX.utils.json_to_sheet(descData);
        XLSX.utils.book_append_sheet(workbook, descSheet, "description");
        hasDownloaded = true;
      }

      // Only save if we have at least one sheet
      if (hasDownloaded) {
        XLSX.writeFile(workbook, `${SITE}_all_images.xlsx`);
      }
    },

    async downloadImagesZip(images, type, index) {
      if (!this.requireProFeature()) {
        return;
      }

      this.imageProgresses[index] = 0;
      try {
        await downloadImagesZip(
          this.productData.title,
          images,
          type,
          (progress) => {
            this.imageProgresses[index] = progress;
          }
        );
      } catch (error) {
        console.error("Download images failed", error);
      }
    },

    downloadExcel(images, type) {
      if (!this.requireProFeature()) {
        return;
      }

      let data;
      if (type === "variant") {
        data = images.map((img) => ({
          variant: img.name,
          image: img.image,
          title: this.productData.title,
        }));
      } else {
        data = images.map((img) => ({ image: img }));
      }
      const worksheet = XLSX.utils.json_to_sheet(data);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, type);
      XLSX.writeFile(workbook, `${type}_images.xlsx`);
    },
  },
};
</script>
