// Download limits utilities

// 免费用户的批量图片、视频、Excel 下载额度：0 表示需升级 Pro
const UNLIMITED_DOWNLOADS = Number.POSITIVE_INFINITY;
export const FREE_DOWNLOADS_PER_DAY = 0;
// 单张图片下载限制：不限
export const FREE_SINGLE_IMAGE_DOWNLOADS_PER_DAY = UNLIMITED_DOWNLOADS;

const STORAGE_KEYS = {
  IMAGE_DOWNLOAD_COUNT: "image_download_count",
  IMAGE_DOWNLOAD_DATE: "image_download_date",
  VIDEO_DOWNLOAD_COUNT: "video_download_count",
  VIDEO_DOWNLOAD_DATE: "video_download_date",
  EXCEL_DOWNLOAD_COUNT: "excel_download_count",
  EXCEL_DOWNLOAD_DATE: "excel_download_date",
  SINGLE_IMAGE_COUNT: "single_image_count",
  SINGLE_IMAGE_DATE: "single_image_date",
};

const FREE_LIMITS = {
  IMAGE_DOWNLOADS_PER_DAY: FREE_DOWNLOADS_PER_DAY,
  VIDEO_DOWNLOADS_PER_DAY: FREE_DOWNLOADS_PER_DAY,
  EXCEL_DOWNLOADS_PER_DAY: FREE_DOWNLOADS_PER_DAY,
};

/**
 * Reset counters if it's a new day
 * @param {string} countKey - The storage key for the count
 * @param {string} dateKey - The storage key for the date
 * @returns {boolean} - Whether the counter was reset
 */
function checkAndResetCounter(countKey, dateKey) {
  const lastDate = localStorage.getItem(dateKey);
  const today = new Date().toISOString().split("T")[0]; // YYYY-MM-DD format

  if (lastDate !== today) {
    localStorage.setItem(countKey, "0");
    localStorage.setItem(dateKey, today);
    return true;
  }

  return false;
}

/**
 * Check if the user has reached their image download limit
 * @returns {boolean} - Whether the user has reached their limit
 */
export function canDownloadImage() {
  checkAndResetCounter(
    STORAGE_KEYS.IMAGE_DOWNLOAD_COUNT,
    STORAGE_KEYS.IMAGE_DOWNLOAD_DATE
  );

  const count = parseInt(
    localStorage.getItem(STORAGE_KEYS.IMAGE_DOWNLOAD_COUNT) || "0",
    10
  );
  return count < FREE_LIMITS.IMAGE_DOWNLOADS_PER_DAY;
}

