/**
 * Increment the image download counter
 */
export function incrementImageDownloadCount() {
  checkAndResetCounter(
    STORAGE_KEYS.IMAGE_DOWNLOAD_COUNT,
    STORAGE_KEYS.IMAGE_DOWNLOAD_DATE
  );

  const count = parseInt(
    localStorage.getItem(STORAGE_KEYS.IMAGE_DOWNLOAD_COUNT) || "0",
    10
  );
  localStorage.setItem(
    STORAGE_KEYS.IMAGE_DOWNLOAD_COUNT,
    (count + 1).toString()
  );
}

