/**
 * Get remaining downloads for today
 * @returns {Object} - Object containing remaining counts
 */
export function getRemainingDownloads() {
  checkAndResetCounter(
    STORAGE_KEYS.IMAGE_DOWNLOAD_COUNT,
    STORAGE_KEYS.IMAGE_DOWNLOAD_DATE
  );
  checkAndResetCounter(
    STORAGE_KEYS.VIDEO_DOWNLOAD_COUNT,
    STORAGE_KEYS.VIDEO_DOWNLOAD_DATE
  );
  checkAndResetCounter(
    STORAGE_KEYS.EXCEL_DOWNLOAD_COUNT,
    STORAGE_KEYS.EXCEL_DOWNLOAD_DATE
  );

  const imageCount = parseInt(
    localStorage.getItem(STORAGE_KEYS.IMAGE_DOWNLOAD_COUNT) || "0",
    10
  );
  const videoCount = parseInt(
    localStorage.getItem(STORAGE_KEYS.VIDEO_DOWNLOAD_COUNT) || "0",
    10
  );
  const excelCount = parseInt(
    localStorage.getItem(STORAGE_KEYS.EXCEL_DOWNLOAD_COUNT) || "0",
    10
  );

  return {
    images: Math.max(0, FREE_LIMITS.IMAGE_DOWNLOADS_PER_DAY - imageCount),
    videos: Math.max(0, FREE_LIMITS.VIDEO_DOWNLOADS_PER_DAY - videoCount),
    excel: Math.max(0, FREE_LIMITS.EXCEL_DOWNLOADS_PER_DAY - excelCount),
  };
}

