import { ref } from "vue";

const messagesByLocale = {};
const currentLocale = ref(getBrowserLanguage());

const loadLocaleMessages = async (locale) => {
  try {
    const response = await fetch(`./_locales/${locale}/messages.json`);
    if (!response.ok) {
      throw new Error(`Failed to fetch messages for locale: ${locale}`);
    }
    return await response.json();
  } catch (error) {
    return null;
  }
};

function getBrowserLanguage() {
  const language = navigator.language || navigator.userLanguage;
  return language.split("-")[0];
}

function resolvePath(obj, path) {
  if (!obj || !path) return undefined;
  return path.split(".").reduce((acc, key) => {
    if (acc && Object.prototype.hasOwnProperty.call(acc, key)) {
      return acc[key];
    }
    return undefined;
  }, obj);
}

const t = (key) => {
  const locale = currentLocale.value;
  const messages = messagesByLocale[locale];
  const fallbackMessages = messagesByLocale.en;
  const value =
    resolvePath(messages, key) ?? resolvePath(fallbackMessages, key);
  if (value != null) {
    return value;
  }
  if (key === "freeUser.message") {
    const freeText = getChromeMessage("free");
    return freeText || "Free";
  }
  if (key === "plan.message") {
    return "Plan";
  }
  const chromeMessage = getChromeMessage(key);
  return chromeMessage || key;
};

function getChromeMessage(key) {
  if (typeof chrome === "undefined" || !chrome?.i18n?.getMessage) {
    return "";
  }
  const baseKey = key.endsWith(".message") ? key.split(".")[0] : key;
  return chrome.i18n.getMessage(baseKey);
}

const ensureLocale = async (locale) => {
  if (messagesByLocale[locale]) {
    return messagesByLocale[locale];
  }
  const messages = await loadLocaleMessages(locale);
  if (messages) {
    messagesByLocale[locale] = messages;
  }
  return messages;
};

(async () => {
  let locale = getBrowserLanguage();
  let messages = await ensureLocale(locale);
  if (!messages) {
    locale = "en";
    await ensureLocale(locale);
  }
  currentLocale.value = locale;
})();

export const setLocale = async (locale) => {
  let messages = await ensureLocale(locale);
  if (!messages) {
    locale = "en";
    await ensureLocale(locale);
  }
  currentLocale.value = locale;
};

export const useI18n = () => ({ t });

const i18n = {
  install(app) {
    app.config.globalProperties.$t = t;
  },
};

export default i18n;
