<template>
  <header class="header">
    <img class="logo" :src="logo" alt="Logo" />
    <span class="title">{{ $t('title.message') }}</span>
    <button
      v-if="authStore.isLoggedIn"
      class="pro-button"
      :class="{ loading: planStore.isLoading }"
      @click="handleClick"
      @mouseover="changeProIcon"
      @mouseout="resetProIcon"
    >
      <template v-if="!planStore.isLoading">
        <img class="pro-icon" :src="currentProIcon" alt="Pro Icon" />
        <span>{{ $t('pro.message') }}</span>
      </template>
      <span
        v-if="planStore.isLoading"
        class="animate-spin-slow inline-block w-5 h-5 border-[2px] border-current border-t-transparent text-main-color rounded-full"
        role="status"
        aria-label="loading"
      ></span>
    </button>
  </header>
</template>
<script>
import { usePlanStore } from "../../store/planStore.js";
import { useAuthStore } from "../../store/authStore";
import { useI18n } from "../../utils/i18n";
export default {
  props: {
    logo: String,
    title: String,
    proIcon: String,
    hoverProIcon: String,
  },
  data() {
    return {
      t: null,
      currentProIcon: "",
      planStore: usePlanStore(),
      authStore: useAuthStore(),
    };
  },
  created() {
    const { t } = useI18n();
    this.t = t; // Assign t from useI18n to the data property
  },
  mounted() {
    this.currentProIcon = this.proIcon;
  },
  methods: {
    changeProIcon() {
      this.currentProIcon = this.hoverProIcon;
    },
    resetProIcon() {
      this.currentProIcon = this.proIcon;
    },
    handleClick() {
    if (!this.planStore.isLoading) {
      this.$emit('switch-to-tab-4');
    }
  }
  },
};
</script>

