<template>
  <div class="tab-content">
    <div class="tabs">
      <button
        v-for="(tab, index) in tabs"
        :key="index"
        class="tab-button"
        :class="{ active: store.activeTabIndex === index }"
        @click="handleTabClick(index)"
      >
        <img
          v-if="!(index === 3 && planStore.isLoading)"
          class="tab-icon"
          :src="tab.icon"
        />

        <span
          v-if="index === 3 && planStore.isLoading"
          class="animate-spin-slow inline-block w-5 h-5 border-[2px] border-current border-t-transparent text-gray-700 rounded-full"
          role="status"
          aria-label="loading"
        ></span>
      </button>
    </div>
    <div class="content">
      <Login v-show="!store.isLoggedIn && store.activeTabIndex === 0" />
      <Tab1 v-show="store.isLoggedIn && store.activeTabIndex === 0" />
      <Tab2
        v-show="store.activeTabIndex === 1"
        :icon-question="iconQuestion"
        :icon-faq="iconFAQ"
        :icon-email="iconEmail"
      />
      <Tab3 v-show="store.isLoggedIn && store.activeTabIndex === 2" />
      <Tab4 v-show="store.isLoggedIn && store.activeTabIndex === 3" />
    </div>
  </div>
</template>


<script setup>
import { useAuthStore } from "../../store/authStore.js"; // 修改
import { usePlanStore } from "../../store/planStore.js";

import Tab1 from "./home/TabHome.vue";
import Tab2 from "./question/TabQuestion.vue";
import Tab3 from "./setting/TabSetting.vue";
import Tab4 from "./vip/TabVip.vue";
import Login from "./login/login.vue";
import { ref, computed } from "vue"; // 请注意此处

const store = useAuthStore(); // 新增
const planStore = usePlanStore();

let tabsBase = [
  { icon: new URL(`../../assets/home.png`, import.meta.url).href },
  { icon: new URL(`../../assets/question.png`, import.meta.url).href },
];

let tabsLoggedIn = [
  ...tabsBase,
  { icon: new URL(`../../assets/setting.png`, import.meta.url).href },
  { icon: new URL(`../../assets/vip.png`, import.meta.url).href },
];

let tabs = computed(() => (store.isLoggedIn ? tabsLoggedIn : tabsBase));
const iconQuestion = new URL(`../../assets/question.png`, import.meta.url).href;
const iconFAQ = new URL(`../../assets/faq.png`, import.meta.url).href;
const iconEmail = new URL(`../../assets/email.png`, import.meta.url).href;

const handleTabClick = (index) => {
  if (index !== 3 || !planStore.isLoading) {
    store.setActiveTabIndex(index)
  }
  if(index == 0 && !planStore.isLoading) {
    planStore.getInfo(false);
  }
}
</script>

