  border-radius: 4px; 
  transition: box-shadow 0.1s, transform 0.1s; 
}

.tab-button:not(.active):hover {
  box-shadow: none; 
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1); 
}

