    <div class="mb-5 flex items-center space-x-4">
      <div class="flex-1 overflow-hidden">
        <div class="flex items-center">
          <p
            class="text-base font-medium text-gray-800"
            :style="{ maxWidth: '310px' }"
            :title="email"
          >
            {{ truncatedEmail }}
          </p>
          <span
            class="ml-2 rounded-full px-2 py-0.5 text-xs font-semibold"
            :class="
              isPro
                ? 'bg-green-100 text-green-700'
                : 'bg-gray-100 text-gray-700'
            "
          >
            {{ isPro ? "PRO" : "FREE" }}
          </span>
        </div>
        <div class="mt-1 flex flex-col text-sm">
          <template v-if="isPro">
            <span>
              <span class="text-gray-600">{{ $t("plan.message") }}: </span>
              <span class="text-gray-700">{{ displayPlanName }} </span>
              <span class="text-gray-500"> | </span>
              <span class="text-xs font-semibold" :class="statusTextClass">
                {{ planStatusToShow }}</span
              >
            </span>
            <span v-if="dateLabel && hasEndsAt">
              <span class="text-gray-600">{{ dateLabel }}: </span>
              <span class="text-gray-700">{{ formattedEndsAt }}</span>
            </span>
            <span v-if="billingEmailToShow">
              <span class="text-gray-600">Billing email: </span>
              <span class="text-gray-700">{{ billingEmailToShow }}</span>
            </span>
          </template>
          <span v-else>
            <span class="text-gray-600">{{ $t("plan.message") }}: </span>
            <span class="text-gray-700">{{ $t("freeUser.message") }} </span>
          </span>
        </div>
      </div>
    </div>

    <button
      v-if="isPro && isSubscriptionPlan"
      class="mb-2 flex w-full items-center justify-center gap-2 rounded-lg border border-gray-300 bg-blue-500 px-5 py-2 text-base font-medium text-white transition-colors hover:bg-blue-600"
      @click="manageSubscription"
    >
      <span>{{ $t("manageSubscription.message") }}</span>
    </button>

    <button
      v-if="!isPro"
      class="mb-2 flex w-full items-center justify-center gap-2 rounded-lg border border-gray-300 bg-blue-500 px-5 py-2 text-base font-medium text-white transition-colors hover:bg-blue-600"
      @click="manageSubscription"
    >
      <span>{{ $t("upgrade.message") }}</span>
    </button>

    <button
      class="flex w-full items-center justify-center gap-2 rounded-md border border-gray-300 bg-white px-5 py-2 text-base font-medium text-gray-800 transition-colors hover:bg-gray-100"
      @click="handleLogout"
    >
      <img class="h-5 w-5" :src="iconLogout" alt="Logout Icon" />
      <span>{{ $t("logout.message") }}</span>
    </button>
  </div>
