<script setup>
import { useAuthStore } from "../../../store/authStore.js";
import { usePlanStore } from "../../../store/planStore.js";
import { APP_ID } from "../../../utils/config.js";
const iconUser = new URL(`../../../assets/user.png`, import.meta.url).href;
const iconLogout = new URL(`../../../assets/logout.png`, import.meta.url).href;
import { ref, computed } from "vue";
import { setLocale } from "../../../utils/i18n";
import { useI18n } from "../../../utils/i18n";
const { t } = useI18n();
const authStore = useAuthStore();
const planStore = usePlanStore();

const handleLogout = async () => {
  await authStore.doLogout();
  authStore.setActiveTabIndex(0);
};

let email = computed(() => authStore.user?.email || "");
let isPro = computed(() => planStore.pro);
let planName = computed(() => planStore.planInfo?.planName || "Monthly");
const subscriptionEmail = computed(() => planStore.planInfo?.subemail || "");
const planStatus = computed(() => planStore.planInfo?.status || "");
const billingMode = computed(() => {
  const raw = planStore.planInfo?.billing_mode || "";
  return raw.replace(/-/g, "_").toLowerCase();
});
const normalizedStatus = computed(() => planStatus.value.toLowerCase());
const statusTextClass = computed(() => {
  const status = normalizedStatus.value;
  if (status === "active") {
    return "text-green-600";
  }
  if (status === "cancelled") {
    return "text-amber-600";
  }
  return "text-gray-600";
});
const planStatusToShow = computed(() => {
  const status = normalizedStatus.value;
  if (!status) {
    return t("active.message");
  }
  return status.charAt(0).toUpperCase() + status.slice(1);
});
const displayPlanName = computed(() => {
  if (!planName.value) return "";
  if (billingMode.value === "one_time") {
    return `${planName.value}, no renewal`;
  }
  return planName.value;
});
const hasEndsAt = computed(() => {
  return !!planStore.planInfo?.ends_at;
});
const formattedEndsAt = computed(() => {
  return formatExpiryDate(planStore.planInfo?.ends_at);
});
const isLifetimePlan = computed(() => {
  if (!planName.value) return false;
  return planName.value.toLowerCase().includes("lifetime");
});
const dateLabel = computed(() => {
  if (!hasEndsAt.value) return "";
  if (billingMode.value === "subscription") {
    if (normalizedStatus.value === "active") {
      return "Renews on";
    }
    if (normalizedStatus.value === "cancelled") {
      return "Ends on";
    }
    return "Ends on";
  }
  if (billingMode.value === "one_time") {
    if (isLifetimePlan.value) {
      return "";
    }
    return "Valid until";
  }
  return "";
});
const isSubscriptionPlan = computed(() => billingMode.value === "subscription");
const billingEmailToShow = computed(() => {
  const sub = subscriptionEmail.value;
  const main = email.value;
  if (!sub) return "";
  if (sub === main) return "";
  return sub;
});

const formatExpiryDate = (dateStr) => {
  if (dateStr === "" || !dateStr || dateStr === "N/A") return "N/A";
  try {
    const date = new Date(dateStr);
    return new Intl.DateTimeFormat("en-US", {
      year: "numeric",
      month: "short",
      day: "numeric",
    }).format(date);
  } catch (e) {
    return dateStr;
  }
};

const truncatedEmail = computed(() => {
  const maxLength = 30;
  if (email.value.length > maxLength) {
    const [localPart, domain] = email.value.split("@");
    const truncatedLocal = localPart.slice(0, 25);
    return `${truncatedLocal}...@${domain}`;
  }
  return email.value;
});

const languages = ref([
  "ar",
  "zh_CN",
  "zh_TW",
  "am",
  "bg",
  "bn",
  "ca",
  "cs",
  "da",
  "de",
  "el",
  "en",
  "es",
  "et",
  "fa",
  "fi",
  "fr",
  "gu",
  "hi",
  "hr",
  "id",
  "it",
  "ja",
  "kn",
  "ko",
  "lt",
  "lv",
  "ml",
  "mr",
  "ms",
  "nl",
  "no",
  "pl",
  "pt",
  "ro",
  "ru",
  "sl",
  "sr",
  "sv",
  "sw",
  "ta",
  "te",
  "th",
  "tr",
  "uk",
  "vi",
]);
const selectedLanguage = ref("en");
const dropdownOpen = ref(false);

const selectLanguage = async (language) => {
  selectedLanguage.value = language;
  dropdownOpen.value = !dropdownOpen.value;
  await setLocale(language);
};

const toggleDropdown = () => {
  dropdownOpen.value = !dropdownOpen.value;
};

const manageSubscription = () => {
  if (isPro.value) {
    const URL = `${import.meta.env.VITE_PAYOUT_MANAGE_URL}?app=${APP_ID}`;
    chrome.tabs.create({ url: URL });
  } else {
    authStore.activeTabIndex = 3;
  }
};
</script>

